import Root from './dot-matrix.svelte';

export {
	Root,
	//
	Root as DotMatrix
};

export type {
	DotMatrixProps as Props,
	DotMatrixAnimation,
	DotMatrixPhase,
	DotMatrixPattern,
	DotMatrixProps
} from './types.js';

import { snakePathNormFromIndex } from './geometry.js';
import type {
	DotAnimationContext,
	DotAnimationResolver,
	DotAnimationState,
	DotMatrixAnimation
} from './types.js';

type PathNormContext = Pick<DotAnimationContext, 'row' | 'col' | 'index'>;
type PathNormGetter = (ctx: PathNormContext) => number;

function createPathWaveResolver(getPathNorm: PathNormGetter): DotAnimationResolver {
	return ({ isActive, row, col, index, reducedMotion, phase }): DotAnimationState => {
		if (!isActive) {
			return { className: 'dmx-inactive' };
		}

		const path = getPathNorm({ row, col, index });
		const style = { '--dmx-path': path };

		if (reducedMotion || phase === 'idle') {
			return {
				style: {
					...style,
					opacity: 0.12 + path * 0.72
				}
			};
		}

		return {
			className: 'dmx-path',
			style
		};
	};
}

const PATH_WAVE_RESOLVER = createPathWaveResolver(({ index }) => snakePathNormFromIndex(index));

export function getAnimationResolver(
	animation: DotMatrixAnimation
): DotAnimationResolver | undefined {
	if (animation === 'path-wave') {
		return PATH_WAVE_RESOLVER;
	}

	return undefined;
}

export const MATRIX_SIZE = 5;
export const MATRIX_CENTER = Math.floor(MATRIX_SIZE / 2);
const RANGE = Array.from({ length: MATRIX_SIZE }, (_, index) => index);
const MAX_RADIUS = Math.hypot(MATRIX_CENTER, MATRIX_CENTER);

const GRID_SIDE = MATRIX_SIZE;
const GRID_CENTER = Math.floor(MATRIX_SIZE / 2);
const CELL_COUNT = GRID_SIDE * GRID_SIDE;
const MAX_TOP_RIGHT_BOTTOM_LEFT = (GRID_SIDE - 1) * 2;
const CORNER_COORDINATES = new Set(['0,0', '0,4', '4,0', '4,4']);

export function rowMajorIndex(row: number, col: number): number {
	return row * MATRIX_SIZE + col;
}

export function indexToCoord(index: number): { row: number; col: number } {
	return {
		row: Math.floor(index / MATRIX_SIZE),
		col: index % MATRIX_SIZE
	};
}

export function distanceFromCenter(index: number): number {
	const { row, col } = indexToCoord(index);
	return Math.hypot(row - MATRIX_CENTER, col - MATRIX_CENTER);
}

export function rowDistance(index: number): number {
	const { row } = indexToCoord(index);
	return Math.abs(row - MATRIX_CENTER);
}

export function polarAngle(index: number): number {
	const { row, col } = indexToCoord(index);
	return Math.atan2(row - MATRIX_CENTER, col - MATRIX_CENTER);
}

export function normalizedRadius(index: number): number {
	const { row, col } = indexToCoord(index);
	return Math.hypot(row - MATRIX_CENTER, col - MATRIX_CENTER) / MAX_RADIUS;
}

export function manhattanDistance(index: number): number {
	const { row, col } = indexToCoord(index);
	return Math.abs(row - MATRIX_CENTER) + Math.abs(col - MATRIX_CENTER);
}

export function harmonicPhase(row: number, col: number, a: number, b: number): number {
	return Math.sin((row + 1) * a + (col + 1) * b);
}

export function lissajousOffset(
	row: number,
	col: number,
	amplitude = 2.25
): { x: number; y: number; phase: number } {
	const x = Math.sin((row + 1) * 1.15 + (col + 1) * 2.2) * amplitude;
	const y = Math.cos((row + 1) * 2.45 + (col + 1) * 0.95) * amplitude;
	const phase = Math.abs(Math.sin((row + 1) * 0.7 + (col + 1) * 1.1));

	return { x, y, phase };
}

export function spiralOffset(
	angle: number,
	radiusNormalizedValue: number,
	amplitude = 2.8
): { x: number; y: number; phase: number } {
	const spin = angle + radiusNormalizedValue * Math.PI * 2.1;
	const radius = radiusNormalizedValue * amplitude;
	const x = Math.cos(spin) * radius;
	const y = Math.sin(spin) * radius;
	const phase = Math.abs(Math.sin(spin * 0.5));

	return { x, y, phase };
}

export function isPrime(value: number): boolean {
	if (value <= 1) {
		return false;
	}

	if (value === 2) {
		return true;
	}

	if (value % 2 === 0) {
		return false;
	}

	const limit = Math.floor(Math.sqrt(value));

	for (let divisor = 3; divisor <= limit; divisor += 2) {
		if (value % divisor === 0) {
			return false;
		}
	}

	return true;
}

export function trBlPathNormFromIndex(index: number): number {
	const { row, col } = indexToCoord(index);
	return (row + (GRID_SIDE - 1 - col)) / MAX_TOP_RIGHT_BOTTOM_LEFT;
}

function buildSnakeOrderToIndexMap(): number[] {
	const pathOrder = new Array<number>(CELL_COUNT);
	let step = 0;

	for (let row = 0; row < GRID_SIDE; row += 1) {
		if (row % 2 === 0) {
			for (let col = 0; col < GRID_SIDE; col += 1) {
				pathOrder[rowMajorIndex(row, col)] = step;
				step += 1;
			}
		} else {
			for (let col = GRID_SIDE - 1; col >= 0; col -= 1) {
				pathOrder[rowMajorIndex(row, col)] = step;
				step += 1;
			}
		}
	}

	return pathOrder;
}

const SNAKE_ORDER: readonly number[] = buildSnakeOrderToIndexMap();

export function snakePathNormFromIndex(index: number): number {
	return SNAKE_ORDER[index]! / (CELL_COUNT - 1);
}

export function snakePathOrderValue(index: number): number {
	return SNAKE_ORDER[index]!;
}

function buildSpiralInwardOrderToIndexMap(): number[] {
	const order = new Array<number>(CELL_COUNT);
	let top = 0;
	let bottom = GRID_SIDE - 1;
	let left = 0;
	let right = GRID_SIDE - 1;
	let step = 0;

	while (top <= bottom && left <= right) {
		for (let col = left; col <= right; col += 1) {
			order[rowMajorIndex(top, col)] = step;
			step += 1;
		}

		for (let row = top + 1; row <= bottom; row += 1) {
			order[rowMajorIndex(row, right)] = step;
			step += 1;
		}

		if (top < bottom) {
			for (let col = right - 1; col >= left; col -= 1) {
				order[rowMajorIndex(bottom, col)] = step;
				step += 1;
			}
		}

		if (left < right) {
			for (let row = bottom - 1; row > top; row -= 1) {
				order[rowMajorIndex(row, left)] = step;
				step += 1;
			}
		}

		top += 1;
		bottom -= 1;
		left += 1;
		right -= 1;
	}

	return order;
}

const SPIRAL_INWARD_ORDER: readonly number[] = buildSpiralInwardOrderToIndexMap();

export function spiralInwardNormFromIndex(index: number): number {
	return SPIRAL_INWARD_ORDER[index]! / (CELL_COUNT - 1);
}

export function spiralInwardOrderValue(index: number): number {
	return SPIRAL_INWARD_ORDER[index]!;
}

function buildOuterRingClockwiseOrderToIndexMap(): number[] {
	const order = new Array<number>(CELL_COUNT).fill(-1);
	const coords: Array<[number, number]> = [
		[0, 0],
		[0, 1],
		[0, 2],
		[0, 3],
		[0, 4],
		[1, 4],
		[2, 4],
		[3, 4],
		[4, 4],
		[4, 3],
		[4, 2],
		[4, 1],
		[4, 0],
		[3, 0],
		[2, 0],
		[1, 0]
	];

	for (let step = 0; step < coords.length; step += 1) {
		const [row, col] = coords[step]!;
		order[rowMajorIndex(row, col)] = step;
	}

	return order;
}

function buildMiddleRingAntiClockwiseOrderToIndexMap(): number[] {
	const order = new Array<number>(CELL_COUNT).fill(-1);
	const coords: Array<[number, number]> = [
		[1, 1],
		[2, 1],
		[3, 1],
		[3, 2],
		[3, 3],
		[2, 3],
		[1, 3],
		[1, 2]
	];

	for (let step = 0; step < coords.length; step += 1) {
		const [row, col] = coords[step]!;
		order[rowMajorIndex(row, col)] = step;
	}

	return order;
}

const OUTER_RING_CLOCKWISE_ORDER: readonly number[] = buildOuterRingClockwiseOrderToIndexMap();
const MIDDLE_RING_ANTI_CLOCKWISE_ORDER: readonly number[] =
	buildMiddleRingAntiClockwiseOrderToIndexMap();

export function outerRingClockwiseOrderValue(index: number): number {
	return OUTER_RING_CLOCKWISE_ORDER[index]!;
}

export function outerRingClockwiseNormFromIndex(index: number): number {
	const order = outerRingClockwiseOrderValue(index);
	return order >= 0 ? order / 15 : 0;
}

export function middleRingAntiClockwiseOrderValue(index: number): number {
	return MIDDLE_RING_ANTI_CLOCKWISE_ORDER[index]!;
}

export function middleRingAntiClockwiseNormFromIndex(index: number): number {
	const order = middleRingAntiClockwiseOrderValue(index);
	return order >= 0 ? order / 7 : 0;
}

function buildDiagonalSnakeOrderToIndexMap(): number[] {
	const order = new Array<number>(CELL_COUNT);
	let step = 0;

	for (let diagonal = 0; diagonal <= (GRID_SIDE - 1) * 2; diagonal += 1) {
		const rowStart = Math.max(0, diagonal - (GRID_SIDE - 1));
		const rowEnd = Math.min(GRID_SIDE - 1, diagonal);

		if (diagonal % 2 === 0) {
			for (let row = rowEnd; row >= rowStart; row -= 1) {
				const col = diagonal - row;
				order[rowMajorIndex(row, col)] = step;
				step += 1;
			}
		} else {
			for (let row = rowStart; row <= rowEnd; row += 1) {
				const col = diagonal - row;
				order[rowMajorIndex(row, col)] = step;
				step += 1;
			}
		}
	}

	return order;
}

const DIAGONAL_SNAKE_ORDER: readonly number[] = buildDiagonalSnakeOrderToIndexMap();

export function diagonalSnakeOrderValue(index: number): number {
	return DIAGONAL_SNAKE_ORDER[index]!;
}

export function diagonalSnakeNormFromIndex(index: number): number {
	return DIAGONAL_SNAKE_ORDER[index]! / (CELL_COUNT - 1);
}

function buildRowWaveSnakeOrderToIndexMap(): number[] {
	const order = new Array<number>(CELL_COUNT);
	const route: Array<{ col: number; dir: 'up' | 'down' }> = [
		{ col: 0, dir: 'up' },
		{ col: 2, dir: 'down' },
		{ col: 1, dir: 'up' },
		{ col: 3, dir: 'down' },
		{ col: 2, dir: 'up' },
		{ col: 4, dir: 'down' }
	];

	let step = 0;

	for (const routeStep of route) {
		if (routeStep.dir === 'up') {
			for (let row = GRID_SIDE - 1; row >= 0; row -= 1) {
				order[rowMajorIndex(row, routeStep.col)] = step;
				step += 1;
			}
		} else {
			for (let row = 0; row < GRID_SIDE; row += 1) {
				order[rowMajorIndex(row, routeStep.col)] = step;
				step += 1;
			}
		}
	}

	return order;
}

const ROW_WAVE_SNAKE_ORDER: readonly number[] = buildRowWaveSnakeOrderToIndexMap();
const ROW_WAVE_SNAKE_MAX_ORDER = Math.max(...ROW_WAVE_SNAKE_ORDER);

export function rowWaveOrderValue(index: number): number {
	return ROW_WAVE_SNAKE_ORDER[index]!;
}

export function rowWaveNormFromIndex(index: number): number {
	return ROW_WAVE_SNAKE_MAX_ORDER > 0 ? rowWaveOrderValue(index) / ROW_WAVE_SNAKE_MAX_ORDER : 0;
}

export function colWaveNormFromIndex(index: number): number {
	const { col } = indexToCoord(index);
	return GRID_SIDE > 1 ? col / (GRID_SIDE - 1) : 0;
}

export function concentricRingNormFromIndex(index: number): number {
	const { row, col } = indexToCoord(index);
	return Math.max(Math.abs(row - GRID_CENTER), Math.abs(col - GRID_CENTER)) / GRID_CENTER;
}

export function isWithinCircularMask(row: number, col: number): boolean {
	return !CORNER_COORDINATES.has(`${row},${col}`);
}

export const GRID_RANGE = RANGE;

import { MATRIX_SIZE } from './geometry.js';

export function stylePx(value: number): string {
	return `${value}px`;
}

export function styleOpacity(opacity: number): number {
	return Math.round(opacity * 1e6) / 1e6;
}

export function styleEntriesToString(
	entries: Record<string, string | number | undefined>
): string | undefined {
	const tokens = Object.entries(entries)
		.filter(([, value]) => value !== undefined && value !== null && value !== '')
		.map(([key, value]) => `${key}: ${typeof value === 'number' ? styleOpacity(value) : value}`);

	return tokens.length > 0 ? tokens.join('; ') : undefined;
}

export function getMatrixLayout(
	size: number,
	dotSize: number,
	cellPadding?: number
): { gap: number; matrixSpan: number } {
	if (cellPadding != null) {
		const gap = Math.max(0, cellPadding);
		const matrixSpan = dotSize * MATRIX_SIZE + gap * (MATRIX_SIZE - 1);
		return { gap, matrixSpan };
	}

	const gap = Math.max(1, Math.floor((size - dotSize * MATRIX_SIZE) / (MATRIX_SIZE - 1)));
	return { gap, matrixSpan: size };
}

export function resolveBoxLayout(
	options: { boxSize?: number; minSize?: number } | null | undefined
): { outerDim: number; useWrapper: boolean } {
	const boxSize = options?.boxSize;
	const hasBoxSize = boxSize != null && boxSize > 0 && Number.isFinite(boxSize);

	if (!hasBoxSize) {
		return { outerDim: 0, useWrapper: false };
	}

	const minSize = options?.minSize;

	if (minSize != null && minSize > 0 && Number.isFinite(minSize)) {
		return { outerDim: Math.max(boxSize, minSize), useWrapper: true };
	}

	return { outerDim: boxSize, useWrapper: true };
}

const SOURCE_BASE_OPACITY = 0.08;
const SOURCE_MID_OPACITY = 0.34;
const SOURCE_PEAK_OPACITY = 0.94;

export const DOT_MATRIX_BLOOM_OPACITY_MIN = 0.6;

function lerp(start: number, end: number, progress: number): number {
	return start + (end - start) * progress;
}

function normalizeProgress(value: number, start: number, end: number): number {
	const span = end - start;

	if (Math.abs(span) < Number.EPSILON) {
		return 0;
	}

	return Math.min(1, Math.max(0, (value - start) / span));
}

function coerceOpacity(value: number | undefined): number | undefined {
	if (value == null || !Number.isFinite(value)) {
		return undefined;
	}

	return Math.min(1, Math.max(0, value));
}

export function clampUnitInterval(value: number | undefined): number | undefined {
	if (value == null || !Number.isFinite(value)) {
		return undefined;
	}

	return Math.min(1, Math.max(0, value));
}

export function remapOpacityToTriplet(
	opacity: number,
	opacityBase: number | undefined,
	opacityMid: number | undefined,
	opacityPeak: number | undefined
): number {
	if (!Number.isFinite(opacity)) {
		return opacity;
	}

	const hasOverrides =
		opacityBase !== undefined || opacityMid !== undefined || opacityPeak !== undefined;
	const safeOpacity = Math.min(1, Math.max(0, opacity));

	if (!hasOverrides) {
		return safeOpacity;
	}

	const targetBase = coerceOpacity(opacityBase) ?? SOURCE_BASE_OPACITY;
	const targetMid = coerceOpacity(opacityMid) ?? SOURCE_MID_OPACITY;
	const targetPeak = coerceOpacity(opacityPeak) ?? SOURCE_PEAK_OPACITY;

	if (safeOpacity <= SOURCE_BASE_OPACITY) {
		const progress = normalizeProgress(safeOpacity, 0, SOURCE_BASE_OPACITY);
		return Math.min(1, Math.max(0, lerp(0, targetBase, progress)));
	}

	if (safeOpacity <= SOURCE_MID_OPACITY) {
		const progress = normalizeProgress(safeOpacity, SOURCE_BASE_OPACITY, SOURCE_MID_OPACITY);
		return Math.min(1, Math.max(0, lerp(targetBase, targetMid, progress)));
	}

	if (safeOpacity <= SOURCE_PEAK_OPACITY) {
		const progress = normalizeProgress(safeOpacity, SOURCE_MID_OPACITY, SOURCE_PEAK_OPACITY);
		return Math.min(1, Math.max(0, lerp(targetMid, targetPeak, progress)));
	}

	const progress = normalizeProgress(safeOpacity, SOURCE_PEAK_OPACITY, 1);
	return Math.min(1, Math.max(0, lerp(targetPeak, 1, progress)));
}

export function opacityToBloomLevel(remappedOpacity: number): number {
	return Math.max(
		0,
		Math.min(
			1,
			(remappedOpacity - DOT_MATRIX_BLOOM_OPACITY_MIN) / (1 - DOT_MATRIX_BLOOM_OPACITY_MIN)
		)
	);
}

export function qualifiesForBloom(remappedOpacity: number): boolean {
	return remappedOpacity >= DOT_MATRIX_BLOOM_OPACITY_MIN;
}

export function clampHalo(value: number | undefined): number {
	if (value == null || !Number.isFinite(value)) {
		return 0;
	}

	return Math.min(1, Math.max(0, value));
}

export function isBloomRootActive(bloom: boolean, halo: number | undefined): boolean {
	return bloom || clampHalo(halo) > 0;
}

export function getBloomHaloSpreadClass(halo: number | undefined): 'dmx-bloom-halo' | undefined {
	return clampHalo(halo) > 0 ? 'dmx-bloom-halo' : undefined;
}

export function getDotBloomParts(
	isActive: boolean,
	curveOpacity: number,
	bloom: boolean,
	halo: number | undefined,
	opacityBase: number | undefined,
	opacityMid: number | undefined,
	opacityPeak: number | undefined
): { level: number; bloomDot: boolean } {
	const haloLevel = clampHalo(halo);

	if (!isActive) {
		return { level: 0, bloomDot: false };
	}

	const remappedOpacity = remapOpacityToTriplet(curveOpacity, opacityBase, opacityMid, opacityPeak);
	const bloomLevel = bloom ? opacityToBloomLevel(remappedOpacity) : 0;

	return {
		level: Math.max(haloLevel, bloomLevel),
		bloomDot: haloLevel > 0 || (bloom && qualifiesForBloom(remappedOpacity))
	};
}

import { GRID_RANGE, MATRIX_CENTER, MATRIX_SIZE, indexToCoord, rowMajorIndex } from './geometry.js';
import type { DotMatrixPattern } from './types.js';

export const FULL_INDEXES = GRID_RANGE.flatMap((row) =>
	GRID_RANGE.map((col) => rowMajorIndex(row, col))
);

export const DIAMOND_INDEXES = FULL_INDEXES.filter((index) => {
	const { row, col } = indexToCoord(index);
	return Math.abs(row - MATRIX_CENTER) + Math.abs(col - MATRIX_CENTER) <= 2;
});

export const OUTLINE_INDEXES = FULL_INDEXES.filter((index) => {
	const { row, col } = indexToCoord(index);
	return row === 0 || row === MATRIX_SIZE - 1 || col === 0 || col === MATRIX_SIZE - 1;
});

export const CROSS_INDEXES = FULL_INDEXES.filter((index) => {
	const { row, col } = indexToCoord(index);
	return row === MATRIX_CENTER || col === MATRIX_CENTER;
});

export const RINGS_INDEXES = FULL_INDEXES.filter((index) => {
	const { row, col } = indexToCoord(index);
	const radius = Math.hypot(row - MATRIX_CENTER, col - MATRIX_CENTER);
	return Math.round(radius) === 1 || Math.round(radius) === 2;
});

export const ROSE_INDEXES = FULL_INDEXES.filter((index) => {
	const { row, col } = indexToCoord(index);
	const dx = col - MATRIX_CENTER;
	const dy = row - MATRIX_CENTER;
	const angle = Math.atan2(dy, dx);
	const radius = Math.hypot(dx, dy);
	const rose = Math.abs(Math.sin(3 * angle));

	return rose > 0.6 && radius >= 1;
});

const PATTERN_INDEXES: Record<DotMatrixPattern, number[]> = {
	diamond: DIAMOND_INDEXES,
	full: FULL_INDEXES,
	outline: OUTLINE_INDEXES,
	rose: ROSE_INDEXES,
	cross: CROSS_INDEXES,
	rings: RINGS_INDEXES
};

export function getPatternIndexes(pattern: DotMatrixPattern = 'diamond'): number[] {
	return PATTERN_INDEXES[pattern];
}

import type { HTMLAttributes } from 'svelte/elements';

type WithoutChildren<T> = T extends { children?: any } ? Omit<T, 'children'> : T;
type WithElementRef<T, U extends HTMLElement = HTMLElement> = T & { ref?: U | null };

export type DotMatrixPattern = 'diamond' | 'full' | 'outline' | 'rose' | 'cross' | 'rings';
export type DotMatrixPhase = 'idle' | 'collapse' | 'hoverRipple' | 'loadingRipple';
export type DotMatrixAnimation = 'none' | 'path-wave';

export interface DotMatrixOptions {
	animation?: DotMatrixAnimation;
	size?: number;
	dotSize?: number;
	color?: string;
	speed?: number;
	pattern?: DotMatrixPattern;
	muted?: boolean;
	bloom?: boolean;
	halo?: number;
	animated?: boolean;
	hoverAnimated?: boolean;
	dotClass?: string;
	opacityBase?: number;
	opacityMid?: number;
	opacityPeak?: number;
	cellPadding?: number;
	boxSize?: number;
	minSize?: number;
}

export type DotMatrixProps = WithoutChildren<WithElementRef<HTMLAttributes<HTMLDivElement>>> &
	DotMatrixOptions;

export type DotMatrixCommonProps = Omit<DotMatrixProps, 'animation'>;

export interface DotAnimationContext {
	index: number;
	row: number;
	col: number;
	distanceFromCenter: number;
	angleFromCenter: number;
	radiusNormalized: number;
	manhattanDistance: number;
	phase: DotMatrixPhase;
	isActive: boolean;
	reducedMotion: boolean;
}

export type DotAnimationStyle = Record<string, string | number | undefined>;

export interface DotAnimationState {
	className?: string;
	style?: DotAnimationStyle;
}

export type DotAnimationResolver = (ctx: DotAnimationContext) => DotAnimationState;

export { createCycleProgress } from './cycle-progress.svelte.js';
export { createDotMatrixPhaseController } from './phase-controller.svelte.js';
export { createReducedMotionQuery } from './reduced-motion.js';
export { createSteppedCycle } from './stepped-cycle.svelte.js';

import { subscribeFrame } from './raf.js';
import { resolveCycleDuration } from './timing.js';

export interface CycleProgressOptions {
	active: () => boolean;
	cycleMsBase: () => number;
	speed?: () => number;
}

export interface CycleProgressController {
	readonly current: number;
}

export function createCycleProgress({
	active,
	cycleMsBase,
	speed = () => 1
}: CycleProgressOptions): CycleProgressController {
	let current = $state(0);

	$effect(() => {
		if (!active()) {
			current = 0;
			return;
		}

		const cycleMs = resolveCycleDuration(cycleMsBase(), speed());
		let start = 0;
		let ready = false;

		return subscribeFrame((now) => {
			if (!ready) {
				start = now;
				ready = true;
			}

			const elapsed = (((now - start) % cycleMs) + cycleMs) % cycleMs;
			current = elapsed / cycleMs;
		});
	});

	return {
		get current() {
			return current;
		}
	};
}

import type { DotMatrixPhase } from '$lib/components/dot-matrix/types.js';

import { resolveSafeSpeed } from './timing.js';

export interface DotMatrixPhaseControllerOptions {
	animated: () => boolean;
	hoverAnimated: () => boolean;
	speed?: () => number;
}

export interface DotMatrixPhaseController {
	readonly phase: DotMatrixPhase;
	onMouseEnter: () => void;
	onMouseLeave: () => void;
}

export function createDotMatrixPhaseController({
	animated,
	hoverAnimated,
	speed = () => 1
}: DotMatrixPhaseControllerOptions): DotMatrixPhaseController {
	let hoverPhase = $state<DotMatrixPhase>('idle');
	let timeouts: number[] = [];
	let hoverGeneration = 0;

	const autoRun = $derived(Boolean(animated() && !hoverAnimated()));

	function clearTimers() {
		for (const timeout of timeouts) {
			window.clearTimeout(timeout);
		}

		timeouts = [];
	}

	$effect(() => {
		autoRun;
		hoverAnimated();
		hoverGeneration += 1;
